{
 "where": "square",
 "clock": "1:00 pm",
 "evidence_now": [
  "Tuesday, February 2, 2016, 1:00 pm.",
  "A bandstand beside the winter festival tent. The town band will play in the afternoon.",
  "The band is playing.",
  "Today the station has one seven o'clock bulletin. The producer can run the portable switcher from anywhere. The reporter has a phone return; the cameraman has a return for footage he has captured. The station plays its ident if nobody takes the switcher."
 ],
 "people_in_earshot": [
  "Phil",
  "Larry"
 ],
 "remembered_experiences": [
  {
   "morning_observation": "Tuesday, February 2, 2016. The local radio plays three bright notes and announces a groundhog forecast in the town square. A delivery van backfires twice.",
   "episodes_in_order": [
    "6:00 am in inn: Rita reaches the square. Phil says: Morning, Rita. I'm just going to hang tight here until 7:00 so the forecast goes out. Let me know if I need to do anything before then. Phil spends the period at the inn. You see Larry at the square.",
    "9:30 am in square: Rita inspects the square. The band is setting up. You see Phil at the square. Larry says: Rita, give me a minute to watch the band get their instruments set up. Larry spends the period at the square."
   ]
  },
  {
   "most_recent_own_plan": "Assess the current setup of the band and identify the best camera position for the afternoon segment."
  }
 ],
